/* eslint-disable no-template-curly-in-string */ //${...}は通常JSの変数や式を展開するためにテンプレートリテラル(`〜`)内で使用するが
//今回はYupのプレースホルダーとして使用するため文字列('〜')として記述、ESLintの警告を出さないために上記の一文は記述するもの、先頭に記述することでファイル全体に適応

import * as yup from 'yup';

const safeTransform = transformFunction => value => (typeof value === 'string' ? transformFunction(value) : value);
//safeTransformは関数を受け取って関数を返す高階関数、transformFunctionの部分で文字列を加工する関数を受け取る、
//valueが文字列以外だった場合も安全に変換できるようにする、Yupの.transform()でnullやundefinedを渡されても落ちない

const schema = yup.object({
  name: yup
    .string()
    .label('名前')
    .transform(safeTransform (value => value//.transform()関数は入力された値をバリデーション前に変換する、変換後の値をバリデーションに回すという
        .normalize('NFKC')//Unicode正規化、英数字などを全角→半角、カナを半角→全角などの正規化
        .replace(/\s+/g, ' ')//\s(全角・半角スペースや改行)+(1回以上の繰り返し)g(全ての一致箇所を取得)、連続スペースを1個にする、姓 名の見栄えの安定のために設定
        .trim()//文字列の先頭と末尾の余分なスペースを削除する(ExcelのTRIM関数とは異なりJSのtrim()関数は文字列内の連続する空白を削除しない)
    ))
    .required('${label}は必須入力です。')
    .max(20, '${label}は${max}文字以内で入力してください。'),
  email: yup
    .string()
    .label('メールアドレス')
    .transform(safeTransform (value =>value
        .normalize('NFKC')
        .trim()
        .toLowerCase()//小文字に統一
    ))
    .required('${label}は必須入力です。')
    .email('${label}の形式が不正です。'),
  title: yup
    .string()
    .label('件名')
    .transform(safeTransform (value => value
        .normalize('NFKC')
        .replace(/\s{2,}/g, ' ')//連続スペースを圧縮
        .trim()
    ))
    .required('${label}は必須入力です。')
    .max(50, '${label}は${max}文字以上で入力してください。'),
  message: yup
    .string()
    .label('本文')
    .transform(safeTransform (value => {
      const normalized = value.normalize('NFKC')
        .replace(/\r\n?/g, '\n')   // 改行コードをLFに統一
        .replace(/[ \t]+$/gm, ''); // 各行末の余計な空白を除去
      return normalized;
    }))
    .test('not-blank', '${label}は必須入力です。', value => !!value && value.trim().length > 0) // 空白だけを弾く
    .required('${label}は必須入力です。')
    .min(10, '${label}は${min}文字以上で入力してください。'),
  agreement: yup
    .boolean()
    .oneOf([true], 'プライバシーポリシーに同意してください'),
});

export default schema;
